1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.section.clazz.Flow;
4	import net.officefloor.server.http.ServerHttpConnection;
5	
6	/**
7	 * First step of {@code POST /api/owners}: honours the optional {@code Idempotency-Key} header.
8	 *
9	 * <p>If the request carries a key that {@link IdempotencyStore} has already seen, the original
10	 * owner is replayed (the {@code replay} branch responds 200) and the create pipeline is skipped
11	 * entirely — no duplicate is persisted. Otherwise (no key, or a first-seen key) the {@code create}
12	 * branch runs the normal validate&rarr;build&rarr;save pipeline; {@link RecordIdempotencyKey}
13	 * remembers the key once the owner has an id.
14	 *
15	 * <p>Exactly one branch is taken, so this step has no {@code next:} — each outcome is an explicit
16	 * flow. The replay branch passes the remembered owner id on as its {@code @Parameter}.
17	 */
18	public class CheckIdempotencyKey {
19	
20	    @FunctionalInterface
21	    public interface CreateFlow {
22	        void create();
23	    }
24	
25	    @FunctionalInterface
26	    public interface ReplayFlow {
27	        void replay(Integer ownerId);
28	    }
29	
30	    public void service(ServerHttpConnection connection, IdempotencyStore store,
31	            @Flow("create") CreateFlow create, @Flow("replay") ReplayFlow replay) {
32	        String key = IdempotencyKeys.from(connection);
33	        Integer existingOwnerId = store.find(key);
34	        if (existingOwnerId != null) {
35	            replay.replay(existingOwnerId);
36	        } else {
37	            create.create();
38	        }
39	    }
40	}
