8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	
10	/**
11	 * Replay branch of {@code POST /api/owners}: a repeat with an already-seen {@code Idempotency-Key}
12	 * reloads the owner first created under that key and returns it with 200 (not 201), so a retried
13	 * create is safe and yields the same owner rather than a duplicate.
14	 */
15	public class ReplayCreatedOwner {
16	
17	    public void service(@Parameter Integer ownerId, OwnerRepository ownerRepository,
18	            OwnerMapper ownerMapper, ObjectResponse<OwnerDto> response) {
19	        Owner owner = ownerRepository.findById(ownerId);
20	        OwnerDto dto = ownerMapper.toOwnerDto(owner);
21	        dto.setBulkSignupWarning(BulkSignup.warning(ownerRepository));
22	        response.send(dto);
23	    }
24	}
