9	/**
10	 * Rejects a create-owner request whose supplied {@code registrationDate} is later than the
11	 * server's current date — a registration cannot be dated in the future. The field is optional:
12	 * an absent registrationDate passes untouched (the server date is used downstream). A supplied
13	 * date on or before today is accepted; anything later is rejected 400 via
14	 * {@link FutureRegistrationDateException}.
15	 */
16	public class RejectFutureRegistrationDate {
17	
18	    public void service(@Val OwnerFieldsDto request) throws FutureRegistrationDateException {
19	        LocalDate registrationDate = request.getRegistrationDate();
20	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
21	            throw new FutureRegistrationDateException(
22	                    "Registration date " + registrationDate + " must not be later than the server date");
23	        }
24	    }
25	}
