1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Map;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.InvalidPostcodeException;
8	
9	/**
10	 * Validates an owner's postcode WHEN PRESENT. A postcode is optional: an absent (null)
11	 * postcode passes untouched, keeping the request contract backward-compatible. When
12	 * present it must be a 4-digit code and, if the city has a known region, fall within that
13	 * region's inclusive postcode range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099); a city
14	 * with no known region accepts any 4-digit postcode. Anything else is rejected 400 via
15	 * {@link InvalidPostcodeException}.
16	 */
17	public class ValidatePostcode {
18	
19	    /** City -> region, matching the fixed table used to derive an owner's locality. */
20	    private static final Map<String, String> CITY_REGION = Map.of(
21	            "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
22	
23	    /** Region -> inclusive 4-digit postcode range {low, high}. */
24	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
25	            "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
26	
27	    public void service(@Val OwnerFieldsDto request) throws InvalidPostcodeException {
28	        String postcode = request.getPostcode();
29	        if (postcode == null) {
30	            return; // optional when absent
31	        }
32	        if (!postcode.matches("^[0-9]{4}$")) {
33	            throw new InvalidPostcodeException("Postcode must be a 4-digit code");
34	        }
35	        String region = CITY_REGION.get(request.getCity());
36	        int[] range = region == null ? null : REGION_POSTCODES.get(region);
37	        if (range == null) {
38	            return; // city with no known region accepts any 4-digit postcode
39	        }
40	        int value = Integer.parseInt(postcode);
41	        if (value < range[0] || value > range[1]) {
42	            throw new InvalidPostcodeException(
43	                    "Postcode " + postcode + " is not valid for city " + request.getCity());
44	        }
45	    }
46	}
