3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
5	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
6	
7	/**
8	 * Validates the create-owner telephone's national-number length against its country code:
9	 * country code '+61' (Australia) requires exactly 9 national digits and '+1' (NANP) requires
10	 * exactly 10 (see {@link E164Telephone#validateNationalNumberLength}). Runs after
11	 * {@link NormalizeOwnerTelephone} (so the published body already carries the E.164 value) and
12	 * before the duplicate checks, so a number whose national length is wrong for its country is
13	 * rejected 400 via {@link InvalidTelephoneException} rather than persisted.
14	 */
15	public class ValidateTelephoneCountryLength {
16	
17	    public void service(@Val OwnerFieldsDto request) throws InvalidTelephoneException {
18	        E164Telephone.validateNationalNumberLength(request.getTelephone());
19	    }
20	}
