1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
6	import org.springframework.samples.petclinic.rest.escalation.CityAtCapacityException;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	
9	/**
10	 * Rejects a create-owner request whose city already contains 50 or more owners. Runs
11	 * before {@link BuildOwner}, counting existing owners in the requested city (same-city
12	 * equality as {@link AssignCustomerCode}). At capacity the request is rejected 409 via
13	 * {@link CityAtCapacityException}.
14	 */
15	public class RejectCityAtCapacity {
16	
17	    private static final int CITY_CAPACITY = 50;
18	
19	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
20	            throws CityAtCapacityException {
21	        String city = request.getCity();
22	        long count = ownerRepository.findAll().stream()
23	                .filter(o -> city == null ? o.getCity() == null : city.equals(o.getCity()))
24	                .count();
25	        if (count >= CITY_CAPACITY) {
26	            throw new CityAtCapacityException(
27	                    "City already contains the maximum number of owners");
28	        }
29	    }
30	}
