29	        String base = OwnerCustomerCode.of(
30	                owner.getPostcode(), owner.getCity(), owner.getTelephone(), owner.getLastName());
31	
32	        Set<String> existing = new HashSet<>();
33	        for (Owner other : ownerRepository.findAll()) {
34	            if (owner.getId() != null && owner.getId().equals(other.getId())) {
35	                continue; // never de-duplicate against the owner being created
36	            }
37	            if (other.isDeleted()) {
38	                continue; // a soft-deleted owner's identity code is free to reuse
39	            }
40	            String code = other.getCustomerCode();
41	            if (code != null) {
42	                existing.add(code);
43	            }
44	        }
45	
46	        String code = base;
47	        for (int n = 2; existing.contains(code); n++) {
48	            code = base + "-" + n;
49	        }
50	        owner.setCustomerCode(code);
51	    }
52	}
