3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.Locale;
7	
8	import net.officefloor.plugin.variable.Val;
9	import org.springframework.samples.petclinic.model.Owner;
10	
11	/**
12	 * Assigns the owner's deterministic {@code householdId}: the first 12 hex characters of
13	 * {@code SHA-256(normalizedLastName + '|' + postcode)}. Because it is derived purely from
14	 * the (last name, postcode) pair, any two owners sharing a last name (compared
15	 * case-insensitively with runs of whitespace collapsed to a single space) and postcode
16	 * receive the <em>same</em> identifier automatically — they are, by definition, the same
17	 * household — and no owner ever has to look up or backfill another. The value never changes
18	 * as more members join.
19	 *
20	 * <p>Runs after {@link BuildOwner} (so the Owner exists) and within the create transaction,
21	 * unconditionally: {@code sharesHousehold} no longer creates the link (the link is implicit
22	 * in the identifier); it only bypasses the later household-duplicate block (see
23	 * {@link RejectDuplicateIdentity}).
24	 */
25	public class AssignHousehold {
26	
27	    public void service(@Val Owner owner) {
28	        String lastName = normalize(owner.getLastName());
29	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode().trim();
30	        owner.setHouseholdId(householdId(lastName, postcode));
31	    }
32	
33	    private static String householdId(String lastName, String postcode) {
34	        byte[] key = (lastName + "|" + postcode).getBytes(StandardCharsets.UTF_8);
35	        MessageDigest digest;
36	        try {
37	            digest = MessageDigest.getInstance("SHA-256");
38	        }
39	        catch (NoSuchAlgorithmException e) {
40	            throw new IllegalStateException("SHA-256 not available", e);
41	        }
42	        byte[] hash = digest.digest(key);
43	        StringBuilder sb = new StringBuilder(64);
44	        for (byte b : hash) {
45	            sb.append(String.format("%02x", b));
46	        }
47	        return sb.substring(0, 12);
48	    }
49	
50	    private static String normalize(String value) {
51	        if (value == null) {
52	            return "";
53	        }
54	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
55	    }
56	}
