8	import org.springframework.samples.petclinic.repository.OwnerRepository;
9	
10	/**
11	 * Flags a create-owner request as a <em>possible</em> (soft) duplicate: one that is not a hard
12	 * duplicate (see {@link RejectDuplicateIdentity}) yet shares an existing owner's
13	 * {@code lastName} (compared case-insensitively with surrounding whitespace trimmed) and
14	 * {@code postcode} while carrying a <em>different</em> telephone (compared in E.164 form, see
15	 * {@link E164Telephone}). Such an owner is still created; it is merely marked so callers can
16	 * review it. When a match is found the owner's {@code possibleDuplicate} is set true and
17	 * {@code possibleDuplicateOf} to the matching owner's id (the earliest such owner by id when
18	 * several match); otherwise {@code possibleDuplicate} is false and {@code possibleDuplicateOf}
19	 * is left unset.
20	 *
21	 * <p>A create that opts in with {@code sharesHousehold} is a <em>declared</em> household member,
22	 * not a suspected one, so it is never flagged: {@code possibleDuplicate} stays false.
23	 *
24	 * <p>Runs after {@link RejectDuplicateIdentity} (so a hard duplicate has already been rejected)
25	 * and within the create transaction, but before {@link SaveOwner}, so the new owner is not yet
26	 * persisted and cannot match itself.
27	 */
28	public class AssignPossibleDuplicate {
29	
30	    public void service(@Val Owner owner, @Val OwnerFieldsDto request, OwnerRepository ownerRepository) {
31	        owner.setPossibleDuplicate(false);
32	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
33	            return; // a declared household member is not a suspected duplicate
34	        }
35	        String lastName = normalize(owner.getLastName());
36	        String postcode = normalize(owner.getPostcode());
37	        if (postcode.isEmpty()) {
38	            return; // no postcode to share on
39	        }
40	        String telephone = E164Telephone.normalizeOrNull(owner.getTelephone());
41	        Integer matchId = null;
42	        for (Owner existing : ownerRepository.findAll()) {
43	            if (owner.getId() != null && owner.getId().equals(existing.getId())) {
44	                continue;
45	            }
46	            if (existing.isDeleted()) {
47	                continue; // a soft-deleted owner is not a possible duplicate
48	            }
49	            if (!normalize(existing.getLastName()).equals(lastName)) {
50	                continue;
51	            }
52	            if (!normalize(existing.getPostcode()).equals(postcode)) {
53	                continue;
54	            }
55	            String existingTelephone = E164Telephone.normalizeOrNull(existing.getTelephone());
56	            if (java.util.Objects.equals(telephone, existingTelephone)) {
57	                continue; // same telephone is not a soft match (it would be a hard duplicate)
58	            }
59	            if (matchId == null || existing.getId() < matchId) {
60	                matchId = existing.getId();
61	            }
62	        }
63	        if (matchId != null) {
64	            owner.setPossibleDuplicate(true);
65	            owner.setPossibleDuplicateOf(matchId);
66	        }
67	    }
68	
69	    private static String normalize(String value) {
70	        return value == null ? "" : value.trim().toLowerCase(Locale.ROOT);
71	    }
72	}
