3	import java.time.DayOfWeek;
4	import java.time.LocalDate;
5	import java.util.Set;
6	
7	/**
8	 * Rolls a registration date forward to a business day: a Saturday, Sunday or listed public
9	 * holiday is rolled forward to the next non-holiday weekday; an ordinary weekday is returned
10	 * unchanged. Used for the effective registration date (supplied on the request or defaulted to
11	 * the server date) so that the stored {@code registrationDate} — and everything derived from it
12	 * — always falls on a business day.
13	 */
14	public final class BusinessDay {
15	
16	    /** Fixed public-holiday calendar. Dates falling on any of these roll forward. */
17	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
18	            LocalDate.of(2026, 1, 1),
19	            LocalDate.of(2026, 1, 26),
20	            LocalDate.of(2026, 4, 25),
21	            LocalDate.of(2026, 12, 25),
22	            LocalDate.of(2026, 12, 28));
23	
24	    private BusinessDay() {
25	    }
26	
27	    public static LocalDate roll(LocalDate date) {
28	        while (isWeekend(date) || PUBLIC_HOLIDAYS.contains(date)) {
29	            date = date.plusDays(1);
30	        }
31	        return date;
32	    }
33	
34	    private static boolean isWeekend(LocalDate date) {
35	        return date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY;
36	    }
37	}
