3	import java.util.concurrent.ConcurrentHashMap;
4	import java.util.concurrent.ConcurrentMap;
5	
6	import org.springframework.stereotype.Component;
7	
8	/**
9	 * Remembers which owner a given {@code Idempotency-Key} first created, so a repeated
10	 * {@code POST /api/owners} carrying an already-seen key replays the original owner (200)
11	 * instead of creating a duplicate (which the identity rules would otherwise reject 409).
12	 *
13	 * <p>A process-wide Spring singleton (not tied to any request or database transaction):
14	 * {@link CheckIdempotencyKey} consults it as the first step of the create pipeline, and
15	 * {@link RecordIdempotencyKey} populates it once the owner has been saved and has an id.
16	 * The mapping is key &rarr; persisted owner id; the replay reloads the owner from the
17	 * repository so the response is built from the current stored state.
18	 */
19	@Component
20	public class IdempotencyStore {
21	
22	    private final ConcurrentMap<String, Integer> keyToOwnerId = new ConcurrentHashMap<>();
23	
24	    /** The owner id previously created under {@code key}, or {@code null} if the key is unseen. */
25	    public Integer find(String key) {
26	        return key == null ? null : keyToOwnerId.get(key);
27	    }
28	
29	    /** Remembers that {@code key} created the owner with {@code ownerId} (first writer wins). */
30	    public void record(String key, Integer ownerId) {
31	        if (key != null && ownerId != null) {
32	            keyToOwnerId.putIfAbsent(key, ownerId);
33	        }
34	    }
35	}
