3	import java.time.LocalDate;
4	
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Bulk sign-up detection: today's business day counts as a bulk sign-up once more than 80
9	 * owners have already been registered on it. "Today" is the server date rolled forward to a
10	 * business day (see {@link BusinessDay}) — the same effective date newly created owners land
11	 * on (see {@link BuildOwner}) and that {@link RejectDailyLimit} caps. The count is of existing
12	 * owners whose {@code registrationDate} equals that business day.
13	 */
14	public final class BulkSignup {
15	
16	    private static final int WARNING_THRESHOLD = 80;
17	
18	    private BulkSignup() {
19	    }
20	
21	    /**
22	     * Returns true when more than 80 owners have already been created for today's business day.
23	     */
24	    public static boolean warning(OwnerRepository ownerRepository) {
25	        LocalDate businessDay = BusinessDay.roll(LocalDate.now());
26	        long count = ownerRepository.findAll().stream()
27	                .filter(o -> businessDay.equals(o.getRegistrationDate()))
28	                .count();
29	        return count > WARNING_THRESHOLD;
30	    }
31	}
